// Tool definition: description decides selection, schema constrains args
const lookupOrderTool = {
  name: "lookup_order",
  description: "Fetch ONE order by exact ID. Use when the ticket names an order. For browsing many orders use search_orders instead.",
  schema: {
    type: "object",
    properties: { orderId: { type: "string", pattern: "^ORD-[0-9]+$" } },
    required: ["orderId"],
    additionalProperties: false,
  },
  run: (db) => (args) => db.orders[args.orderId] || { error: "not-found" },
};
// Pattern-constrained IDs, closed schemas, documented siblings.

// Tool-call executor: validate args, run, route outcomes (plain JS)
function execTool(tool, args, state) {
  const problems = [];
  for (const key of tool.schema.required || [])
    if (!(key in args)) problems.push("missing:" + key);
  if (tool.schema.properties?.orderId?.pattern) {
    const re = new RegExp(tool.schema.properties.orderId.pattern);
    if (args.orderId && !re.test(args.orderId)) problems.push("bad-format:orderId");
  }
  if (problems.length) return { next: "quarantine", update: { toolError: problems } };
  const result = tool.run(state.db)(args);
  if (result && result.error) return { next: "clarify", update: { toolError: result.error } };
  return { next: "continue", update: { toolResult: result } };
}
// Three exits: continue (value), clarify (empty/error), quarantine (invalid args).

