function execToolCall(args) {
  const problems = [];
  if (!('orderId' in args)) problems.push('missing:orderId');
  else if (!/^ORD-[0-9]+$/.test(args.orderId)) problems.push('bad-format:orderId');
  if (problems.length) return { next: 'quarantine', problems };
  const db = { 'ORD-4821': { total: 129 } };
  const hit = db[args.orderId];
  if (!hit) return { next: 'clarify', problems: ['not-found'] };
  return { next: 'continue', result: hit };
}
const cases = [
  [{ orderId: 'ORD-4821' }, 'continue'],
  [{ orderId: 'ORD-9999' }, 'clarify'],
  [{ orderId: 'ten' }, 'quarantine'],
  [{}, 'quarantine'],
];
let pass = 0;
for (const [args, expected] of cases) {
  const got = execToolCall(args).next;
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(args) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' tool calls routed');

